package settings

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"log/slog"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"sync"

	"github.com/bmatcuk/doublestar/v4"
	"github.com/entireio/cli/cmd/entire/cli/gitremote"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// UserSettingsFileName is the basename of the user-global settings file inside
// userdirs.Config(). It sits beside contexts.json and holds machine-wide
// configuration that is not tied to any repository.
const UserSettingsFileName = "settings.json"

// caseInsensitivePaths folds exclude_paths matching on macOS and Windows,
// whose default filesystems are case-insensitive: the worktree root's casing
// varies with how the agent was launched.
var caseInsensitivePaths = runtime.GOOS == "darwin" || runtime.GOOS == "windows"

// GlobalConfig is the "global" section of the user-global settings file.
// It controls global auto-enable: tracking agent sessions in repositories
// that have no repo-level Entire setup.
type GlobalConfig struct {
	// Enabled turns global mode on. Both true and false count as configured.
	Enabled bool `json:"enabled"`

	// ExcludePaths are ~-expanded doublestar globs matched against a
	// repository's worktree root. Any match excludes that worktree.
	ExcludePaths []string `json:"exclude_paths,omitempty"`

	// ExcludeOrigins are doublestar globs matched against the origin remote
	// URL normalized to host/owner/repo. A repo without an origin matches
	// no origin pattern. Origins stored via git insteadOf shorthands (e.g.
	// gh:acme/widgets) normalize to the shorthand form, not the expanded
	// host — patterns match what git config stores.
	ExcludeOrigins []string `json:"exclude_origins,omitempty"`
}

// UserSettings is the root of the user-global settings file.
type UserSettings struct {
	Global *GlobalConfig `json:"global,omitempty"`
}

// UserSettingsPath returns the absolute path of the user-global settings
// file, for callers that name it in error messages.
func UserSettingsPath() string {
	return filepath.Join(userdirs.Config(), UserSettingsFileName)
}

// LoadUserSettings reads the user-global settings file. A missing file is not
// an error: it returns an empty UserSettings (Global == nil, meaning the
// global tier is unconfigured). A malformed file returns an error; callers on
// the hook path must treat that as global-off (fail closed).
func LoadUserSettings(_ context.Context) (*UserSettings, error) {
	// Deliberately plain os.ReadFile: readConfined/os.Root rejects absolute
	// symlinks, and ~/.config/entire/settings.json is commonly symlinked by
	// dotfile managers — with fail-closed semantics that would silently
	// disable global mode.
	data, err := os.ReadFile(UserSettingsPath())
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return &UserSettings{}, nil
		}
		return nil, fmt.Errorf("reading user settings: %w", err)
	}
	// Strict decoding: a typo'd exclude key silently failing open (tracking a
	// repo the user meant to exclude) is worse than an older CLI rejecting a
	// newer file, which fails closed and is therefore safe.
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var us UserSettings
	if err := dec.Decode(&us); err != nil {
		return nil, fmt.Errorf("parsing user settings: %w", err)
	}
	return &us, nil
}

// SaveUserSettings writes the user-global settings file atomically (temp file
// in userdirs.Config() + rename, 0o600), creating the config directory if
// needed. It writes exactly the known schema: unknown keys are never
// preserved, by design — LoadUserSettings decodes strictly, so a load-modify-
// save cycle against a newer file fails at load rather than silently dropping
// keys here. It also resets the process-level caches derived from the file
// (the GlobalModeActive memo and the invisible-routing decision), so a writer
// process observes its own write.
func SaveUserSettings(_ context.Context, us *UserSettings) error {
	dir := userdirs.Config()
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("creating config directory: %w", err)
	}
	data, err := jsonutil.MarshalIndentWithNewline(us, "", "  ")
	if err != nil {
		return fmt.Errorf("encoding user settings: %w", err)
	}
	if err := jsonutil.WriteFileAtomic(UserSettingsPath(), data, 0o600); err != nil {
		return fmt.Errorf("writing user settings: %w", err)
	}
	ClearGlobalModeCache()
	paths.ClearInvisibleRuntimeCache()
	return nil
}

// normalizeOrigin reduces a git remote URL to lowercase "host/owner/repo" for
// exclude_origins matching. ssh and https forms of the same repo normalize
// identically. Unparseable input returns "" (matches no pattern).
func normalizeOrigin(rawURL string) string {
	if rawURL == "" {
		return ""
	}
	info, err := gitremote.ParseURL(rawURL)
	if err != nil || info == nil || info.Owner == "" || info.Repo == "" {
		return ""
	}
	return strings.ToLower(info.CanonicalHost() + "/" + info.Owner + "/" + info.Repo)
}

// expandTilde expands a leading "~" or "~/" to the user home directory and
// cleans the result, so a trailing slash cannot break matching. Returns ""
// for patterns that cannot be resolved: empty input, an unavailable home dir,
// the unsupported "~user" form, or a relative pattern (which can never match
// an absolute worktree root).
func expandTilde(pattern string) string {
	if pattern == "" {
		return ""
	}
	if pattern == "~" || strings.HasPrefix(pattern, "~/") {
		home, err := os.UserHomeDir()
		if err != nil {
			return ""
		}
		return filepath.ToSlash(filepath.Join(home, strings.TrimPrefix(pattern, "~")))
	}
	if strings.HasPrefix(pattern, "~") {
		return ""
	}
	slashed := filepath.ToSlash(filepath.Clean(pattern))
	if !strings.HasPrefix(slashed, "/") && !filepath.IsAbs(pattern) {
		return ""
	}
	return slashed
}

// matchesExcludePath reports whether worktreeRoot matches any exclude_paths
// pattern. A pattern also excludes everything under it (p matches, or p/**
// matches). Broken patterns (unexpandable ~, relative, invalid glob) are
// skipped so one bad entry cannot disable the rest of the exclude list.
func matchesExcludePath(ctx context.Context, patterns []string, worktreeRoot string) bool {
	return matchesExcludePathFold(ctx, patterns, worktreeRoot, caseInsensitivePaths)
}

// matchesExcludePathFold is the fold-explicit seam behind matchesExcludePath,
// letting tests exercise both case sensitivities on every platform.
func matchesExcludePathFold(ctx context.Context, patterns []string, worktreeRoot string, fold bool) bool {
	root := filepath.ToSlash(worktreeRoot)
	if fold {
		root = strings.ToLower(root)
	}
	for i, p := range patterns {
		expanded := expandTilde(p)
		if expanded == "" {
			logging.Debug(ctx, "skipping unexpandable exclude_paths pattern",
				slog.Int("pattern_index", i))
			continue
		}
		if fold {
			expanded = strings.ToLower(expanded)
		}
		ok, err := doublestar.Match(expanded, root)
		if err != nil {
			logging.Debug(ctx, "skipping invalid exclude_paths glob",
				slog.Int("pattern_index", i), slog.String("error", err.Error()))
			continue
		}
		if ok {
			return true
		}
		if ok, err := doublestar.Match(expanded+"/**", root); err == nil && ok {
			return true
		}
	}
	return false
}

// matchesExcludeOrigin reports whether the normalized origin ("host/owner/repo")
// matches any exclude_origins pattern. An empty origin matches nothing.
func matchesExcludeOrigin(ctx context.Context, patterns []string, normalizedOrigin string) bool {
	if normalizedOrigin == "" {
		return false
	}
	for i, p := range patterns {
		ok, err := doublestar.Match(strings.ToLower(p), normalizedOrigin)
		if err != nil {
			logging.Debug(ctx, "skipping invalid exclude_origins glob",
				slog.Int("pattern_index", i), slog.String("error", err.Error()))
			continue
		}
		if ok {
			return true
		}
	}
	return false
}

// InactiveReason explains why the hook gate found Entire inactive for the
// current worktree. It exists so the SessionStart wrong-folder notice can name
// the reason without re-deriving (and possibly contradicting) the gate's
// decision. InactiveReasonNone accompanies an active result.
type InactiveReason int

const (
	// InactiveReasonNone: not inactive (the location is active).
	InactiveReasonNone InactiveReason = iota
	// InactiveReasonRepoDisabled: repo-level setup exists and is disabled (or
	// unreadable — fail closed). This is an explicit veto: callers surfacing
	// inactive-location notices must stay silent for it.
	InactiveReasonRepoDisabled
	// InactiveReasonGlobalExcluded: the global tier is on, but this worktree
	// matches an exclude pattern (or exclusion could not be verified — fail
	// closed).
	InactiveReasonGlobalExcluded
	// InactiveReasonGlobalOff: no repo-level setup, and the global tier is
	// unconfigured, disabled, or unreadable.
	InactiveReasonGlobalOff
)

// globalModeCache memoizes the global-mode probe per worktree root. Hooks are
// one-shot processes that evaluate the gate more than once (logging init plus
// the entry gate), and the exclude_origins check forks git each time; one
// probe per process removes that cost and guarantees every gate in the
// process sees one consistent answer. The root key keeps in-process tests
// with multiple temp repos isolated (same pattern as the invisible-routing
// cache in paths).
var (
	globalModeMu     sync.Mutex
	globalModeRoot   string
	globalModeCached bool
	globalModeActive bool
	globalModeReason InactiveReason
)

// ClearGlobalModeCache resets the memoized global-mode probe result.
// For tests that flip user-global settings mid-process; SaveUserSettings also
// calls it so a writer process observes its own write.
func ClearGlobalModeCache() {
	globalModeMu.Lock()
	globalModeRoot = ""
	globalModeCached = false
	globalModeActive = false
	globalModeReason = InactiveReasonNone
	globalModeMu.Unlock()
}

// GlobalModeActive reports whether the user-global tier activates Entire for
// the current worktree: the global tier is configured and enabled, the
// worktree is resolvable, and no exclude pattern matches. Every error path
// returns false (fail closed) — a hook must never proceed on a guess. A repo
// with no origin remote stays active (it matches no origin pattern), but a
// failed origin lookup deactivates: exclusion could not be checked.
// The result is memoized per process (see globalModeCache above).
func GlobalModeActive(ctx context.Context) bool {
	active, _ := globalModeStatus(ctx)
	return active
}

// globalModeStatus is GlobalModeActive plus the inactive reason, memoized
// together so both callers observe one consistent answer per process.
func globalModeStatus(ctx context.Context) (bool, InactiveReason) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return false, InactiveReasonGlobalOff
	}
	globalModeMu.Lock()
	defer globalModeMu.Unlock()
	if globalModeCached && globalModeRoot == root {
		return globalModeActive, globalModeReason
	}
	active, reason := computeGlobalModeStatus(ctx, root)
	globalModeRoot = root
	globalModeCached = true
	globalModeActive = active
	globalModeReason = reason
	return active, reason
}

// computeGlobalModeStatus is the uncached evaluation behind globalModeStatus.
func computeGlobalModeStatus(ctx context.Context, root string) (bool, InactiveReason) {
	us, err := LoadUserSettings(ctx)
	if err != nil {
		logging.Debug(ctx, "user settings unreadable; treating global mode as inactive",
			slog.String("error", err.Error()))
		return false, InactiveReasonGlobalOff
	}
	if us.Global == nil || !us.Global.Enabled {
		return false, InactiveReasonGlobalOff
	}
	if matchesExcludePath(ctx, us.Global.ExcludePaths, root) {
		return false, InactiveReasonGlobalExcluded
	}
	if len(us.Global.ExcludeOrigins) > 0 {
		origins, _, err := gitremote.GetRemoteURLsInDirIfSet(ctx, root, "origin")
		if err != nil {
			logging.Debug(ctx, "origin lookup failed; treating global mode as inactive",
				slog.String("error", err.Error()))
			return false, InactiveReasonGlobalExcluded
		}
		for _, origin := range origins {
			if matchesExcludeOrigin(ctx, us.Global.ExcludeOrigins, normalizeOrigin(origin)) {
				return false, InactiveReasonGlobalExcluded
			}
		}
	}
	return true, InactiveReasonNone
}

// IsActiveForRepo is the gate predicate for hooks: is Entire active for the
// current worktree, via either repo-level setup or the user-global tier?
//
//	repo setup | repo enabled | global tier              | result
//	-----------+--------------+---------------------------+-------
//	yes        | true         | (ignored)                 | true
//	yes        | false        | (ignored)                 | false (explicit veto)
//	yes        | read error   | (ignored)                 | false (fail closed)
//	no         | —            | enabled and not excluded  | true
//	no         | —            | otherwise                 | false
//
// The global tier is a fallback, not a merge layer: any repo-level setup
// (either settings file) makes the repo-level answer final.
func IsActiveForRepo(ctx context.Context) bool {
	active, _ := IsActiveForRepoWithReason(ctx)
	return active
}

// GlobalTierEnabled reports whether the user-global tracking tier is
// configured AND enabled, independent of any repository context. It exists
// for the one gate that runs where the worktree-scoped reason variant cannot:
// the SessionStart wrong-folder notice outside a git repository. Deliberately
// unmemoized — it is only called on that cold path (session-start verb, no
// repo), so the active hook path pays nothing for it. Fail closed on read
// errors, like every other gate over this file.
func GlobalTierEnabled(ctx context.Context) bool {
	us, err := LoadUserSettings(ctx)
	if err != nil {
		return false
	}
	return us.Global != nil && us.Global.Enabled
}

// IsActiveForRepoWithReason is IsActiveForRepo plus the reason a location is
// inactive, for callers that surface a notice (the SessionStart wrong-folder
// warning). It must stay the same decision as IsActiveForRepo — the reason is
// derived inside the gate, never re-computed by callers.
func IsActiveForRepoWithReason(ctx context.Context) (bool, InactiveReason) {
	if IsSetUpAny(ctx) {
		if IsSetUpAndEnabled(ctx) {
			return true, InactiveReasonNone
		}
		return false, InactiveReasonRepoDisabled
	}
	return globalModeStatus(ctx)
}

package paths

import (
	"context"
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"

	"github.com/entireio/cli/internal/entireclient/userdirs"
)

// Invisible-mode routing.
//
// A repo tracked only by the user-global settings tier (no
// .entire/settings.json or .entire/settings.local.json in the worktree,
// global.enabled true in the user settings file) must never gain files in the
// worktree — that is the product guarantee of global tracking. AbsPath
// therefore reroutes the runtime-data directories below from
// <worktree>/.entire/<sub> to
// <git-common-dir>/entire/worktree/<worktree-key>/<sub> for such repos. The
// worktree key namespaces the shared common dir per worktree (linked
// worktrees of one clone share the common dir but must not interleave
// runtime data); it is the same worktree-ID hash shadow branch names use.
// Any repo-level setup pins every path to the worktree, byte-identical to
// the historical behavior.

// invisibleRuntimeSubdir is the directory inside the git common dir that
// holds rerouted runtime data, one <worktree-key> namespace per worktree.
// It sits next to entire/preferences.json.
const invisibleRuntimeSubdir = "entire/worktree"

// InvisibleRuntimeDir returns the directory invisible routing resolves
// runtime data under for the worktree rooted at root, given the repo's
// absolute git common dir: <commonDir>/entire/worktree/<worktree-key>.
// The key is HashWorktreeID over the worktree's git identifier ("" for the
// main worktree), so every worktree of a clone gets its own namespace.
// This is the single source of truth for the layout — the enable-time
// migration (setup_global.go) uses it to move only the current worktree's
// namespace.
func InvisibleRuntimeDir(commonDir, root string) (string, error) {
	worktreeID, err := GetWorktreeID(root)
	if err != nil {
		return "", err
	}
	return filepath.Join(commonDir, filepath.FromSlash(invisibleRuntimeSubdir), HashWorktreeID(worktreeID)), nil
}

// settingsLocalFileName mirrors settings.EntireSettingsLocalFile's basename.
// The settings package imports paths, so the constant cannot be shared.
const settingsLocalFileName = "settings.local.json"

// runtimeDataPrefixes are the .entire subtrees that hold runtime data (as
// opposed to configuration). Only these are ever rerouted: settings files,
// .entire/.gitignore, and redactor packs must stay worktree-resolved — the
// settings files' worktree presence is itself the routing discriminator.
var runtimeDataPrefixes = []string{EntireMetadataDir, EntireLogsDir, EntireTmpDir}

// runtimeDataSubpath reports whether relPath addresses runtime data and, if
// so, returns its path relative to the .entire directory (slash-separated,
// e.g. "metadata/<session>/prompt.txt").
func runtimeDataSubpath(relPath string) (string, bool) {
	rel := filepath.ToSlash(relPath)
	for _, prefix := range runtimeDataPrefixes {
		if rel == prefix || strings.HasPrefix(rel, prefix+"/") {
			return strings.TrimPrefix(rel, EntireDir+"/"), true
		}
	}
	return "", false
}

// invisibleBaseCache caches the routing decision per worktree root. Hooks are
// one-shot processes, so one probe per process is enough; the root key keeps
// in-process tests with multiple temp repos isolated.
var (
	invisibleMu        sync.Mutex
	invisibleCacheRoot string
	invisibleCacheBase string
)

// ClearInvisibleRuntimeCache clears the cached invisible-routing decision.
// Primarily useful for tests that change global settings for one repo root.
func ClearInvisibleRuntimeCache() {
	invisibleMu.Lock()
	invisibleCacheRoot = ""
	invisibleCacheBase = ""
	invisibleMu.Unlock()
}

// invisibleRuntimeBase returns the absolute directory runtime data resolves
// under for the repo rooted at root (the caller's already-resolved worktree
// root), or "" when it lives in the worktree (repo-level setup present,
// global tier off, or any probe failure — every error path keeps today's
// worktree behavior).
func invisibleRuntimeBase(ctx context.Context, root string) string {
	invisibleMu.Lock()
	defer invisibleMu.Unlock()
	if invisibleCacheRoot == root {
		return invisibleCacheBase
	}
	base := computeInvisibleRuntimeBase(ctx, root)
	invisibleCacheRoot = root
	invisibleCacheBase = base
	return base
}

func computeInvisibleRuntimeBase(ctx context.Context, root string) string {
	// Any repo-level setup — either settings scope — pins .entire to the
	// worktree. Lstat (not Stat) matches settings.IsSetUpAny: a dangling
	// symlink still counts as setup.
	for _, name := range []string{SettingsFileName, settingsLocalFileName} {
		if _, err := os.Lstat(filepath.Join(root, EntireDir, name)); err == nil {
			return ""
		}
	}
	if !userGlobalTierEnabled() {
		return ""
	}
	commonDir, err := gitCommonDir(ctx)
	if err != nil {
		return ""
	}
	base, err := InvisibleRuntimeDir(commonDir, root)
	if err != nil {
		return ""
	}
	return base
}

// userGlobalTierEnabled reports whether the user-global settings file enables
// global mode. This is a minimal mirror of settings.LoadUserSettings +
// GlobalModeActive's enabled bit — paths cannot import settings (settings
// imports paths), and the full gate (strict decoding, exclude lists) stays in
// settings where hooks consult it.
//
// Divergence from the strict gate is deliberately one-sided: lenient
// decoding and no exclude lists make this probe a strict superset of the
// strict gate, so divergence can only route reads to an empty .git-side
// location, never produce worktree writes.
func userGlobalTierEnabled() bool {
	// settings.json inside userdirs.Config() = settings.UserSettingsFileName.
	data, err := os.ReadFile(filepath.Join(userdirs.Config(), "settings.json"))
	if err != nil {
		return false
	}
	var us struct {
		Global *struct {
			Enabled bool `json:"enabled"`
		} `json:"global"`
	}
	if json.Unmarshal(data, &us) != nil {
		return false
	}
	return us.Global != nil && us.Global.Enabled
}

// gitCommonDir returns the absolute git common dir for the current working
// directory. Corrected copy of session.GetGitCommonDir — importing session
// (or strategy) here would cycle back into paths via logging — with two
// deliberate differences: a relative `git rev-parse --git-common-dir` result
// is absolutized via filepath.Abs (session's filepath.Join(".", dir) leaves
// it relative), and there is no per-cwd cache (invisibleRuntimeBase already
// caches the final routing decision per worktree root). Do not unify this
// back onto session's weaker behavior.
func gitCommonDir(ctx context.Context) (string, error) {
	out, err := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir").Output()
	if err != nil {
		return "", err //nolint:wrapcheck // internal helper; callers only branch on failure
	}
	dir := strings.TrimSpace(string(out))
	if !filepath.IsAbs(dir) {
		abs, absErr := filepath.Abs(dir)
		if absErr != nil {
			return "", absErr //nolint:wrapcheck // internal helper; callers only branch on failure
		}
		dir = abs
	}
	return filepath.Clean(dir), nil
}

package paths

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
	"sync"
	"unicode"
)

// Directory constants
const (
	EntireDir         = ".entire"
	EntireTmpDir      = ".entire/tmp"
	EntireMetadataDir = ".entire/metadata"
	EntireLogsDir     = ".entire/logs"

	osWindows = "windows"
	osDarwin  = "darwin"
)

// Metadata file names
const (
	PromptFileName           = "prompt.txt"
	TranscriptFileName       = "full.jsonl"
	TranscriptFileNameLegacy = "full.log"
	// CompactTranscriptFileName is the compact transcript stored alongside
	// full.jsonl. It holds the full compacted session; this checkpoint's slice
	// begins at the session metadata's compact_transcript_start.
	CompactTranscriptFileName = "transcript.jsonl"
	MetadataFileName          = "metadata.json"
	CheckpointFileName        = "checkpoint.json"
	ContentHashFileName       = "content_hash.txt"
	SettingsFileName          = "settings.json"

	// AssetsDir is the per-session subfolder holding externalized transcript
	// assets (e.g. images); AssetsManifestFile indexes them. AssetsDirName is the
	// bare tree-entry name (no trailing slash) used when walking git trees.
	AssetsDirName      = "assets"
	AssetsDir          = "assets/"
	AssetsManifestFile = "assets/manifest.json"
)

// MetadataBranchName is the orphan branch used by manual-commit strategy to store metadata
const MetadataBranchName = "entire/checkpoints/v1"

// TrailsBranchName is the orphan branch used to store trail metadata.
// Trails are branch-centric work tracking abstractions that link to checkpoints by branch name.
const TrailsBranchName = "entire/trails/v1"

// worktreeRootCache caches the worktree root to avoid repeated git commands.
// The cache is keyed by the current working directory to handle directory changes.
var (
	worktreeRootMu       sync.RWMutex
	worktreeRootCache    string
	worktreeRootCacheDir string
)

// WorktreeRoot returns the git worktree root directory.
// Uses 'git rev-parse --show-toplevel' which returns the working tree toplevel.
// In a worktree this is the worktree root, not the main repository root.
// The result is cached per working directory.
// Returns an error if not inside a git repository.
func WorktreeRoot(ctx context.Context) (string, error) {
	// Get current working directory to check cache validity
	cwd, err := os.Getwd() //nolint:forbidigo // already present in codebase
	if err != nil {
		cwd = ""
	}

	// Check cache with read lock first
	worktreeRootMu.RLock()
	if worktreeRootCache != "" && worktreeRootCacheDir == cwd {
		cached := worktreeRootCache
		worktreeRootMu.RUnlock()
		return cached, nil
	}
	worktreeRootMu.RUnlock()

	// Cache miss - get worktree root and update cache with write lock
	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
	output, err := cmd.Output()
	if err != nil {
		return "", fmt.Errorf("failed to get git worktree root: %w", err)
	}

	root := strings.TrimSpace(string(output))

	worktreeRootMu.Lock()
	worktreeRootCache = root
	worktreeRootCacheDir = cwd
	worktreeRootMu.Unlock()

	return root, nil
}

// ClearWorktreeRootCache clears the cached worktree root.
// This is primarily useful for testing when changing directories.
func ClearWorktreeRootCache() {
	worktreeRootMu.Lock()
	worktreeRootCache = ""
	worktreeRootCacheDir = ""
	worktreeRootMu.Unlock()
}

// AbsPath returns the absolute path for a relative path within the repository.
// If the path is already absolute, it is returned as-is.
// Uses WorktreeRoot() to resolve paths relative to the worktree root.
//
// Exception: runtime-data paths (.entire/metadata, .entire/logs, .entire/tmp)
// in a repo tracked only by the user-global tier resolve under the git common
// dir instead of the worktree, so a globally tracked repo never gains worktree
// files (see invisibleRuntimeBase in invisible.go). Repos with any repo-level
// setup resolve every path to the worktree, exactly as before.
func AbsPath(ctx context.Context, relPath string) (string, error) {
	if filepath.IsAbs(relPath) {
		return relPath, nil
	}

	root, err := WorktreeRoot(ctx)
	if err != nil {
		return "", err
	}

	if sub, ok := runtimeDataSubpath(relPath); ok {
		if base := invisibleRuntimeBase(ctx, root); base != "" {
			return filepath.Join(base, filepath.FromSlash(sub)), nil
		}
	}

	return filepath.Join(root, relPath), nil
}

// IsInfrastructurePath returns true if the path is part of CLI infrastructure
// (i.e., inside the .entire directory). It is used only to EXCLUDE infra paths
// from checkpoints/tracking, so it matches case-insensitively on
// case-insensitive filesystems via IsProtectedSubpath. Do not use it as a
// containment/allow gate.
func IsInfrastructurePath(path string) bool {
	return IsProtectedSubpath(EntireDir, path)
}

// IsSubpath reports whether child is lexically under parent (or equal to it).
// It uses filepath.Rel, which cleans both inputs and is traversal-resistant:
// a crafted child like "/a/b/../../../etc/passwd" that escapes parent will
// produce a relative path starting with ".." and be rejected.
//
// Matching is case-SENSITIVE. This is the correct primitive for fail-closed
// containment/allow checks (e.g. validating an attacker-influenced path stays
// under an Entire-owned dir): on a case-sensitive volume a differently-cased
// path names a different directory, so folding it in would fail open. For
// EXCLUSION decisions that must also catch case variants on Windows/macOS, use
// IsProtectedSubpath instead.
func IsSubpath(parent, child string) bool {
	rel, err := filepath.Rel(parent, child)
	if err != nil {
		return false
	}
	return !IsRelativeTraversal(rel)
}

// IsProtectedSubpath reports whether child is under parent for the purpose of
// EXCLUDING protected/infrastructure content from checkpoints and tracking.
// Unlike IsSubpath it honors OS case-insensitivity (see CaseInsensitiveFS), so
// a case variant of a protected dir (".Claude" vs ".claude") is still excluded
// on Windows/macOS.
//
// SECURITY: never use this for allow/containment decisions. Case-folding widens
// what counts as "inside" parent, which is safe only when the effect is to
// exclude more. On a case-sensitive volume under a case-insensitive GOOS it
// over-matches; for a fail-closed gate that would fail open. Use IsSubpath there.
func IsProtectedSubpath(parent, child string) bool {
	if CaseInsensitiveFS() {
		return IsSubpath(strings.ToLower(parent), strings.ToLower(child))
	}
	return IsSubpath(parent, child)
}

// CaseInsensitiveFS reports whether path comparisons should be case-insensitive
// on the host OS. This is OS-based, not volume-based: Windows and macOS default
// to case-insensitive filesystems, Linux to case-sensitive. Keying on GOOS keeps
// the result deterministic. It must only influence EXCLUSION decisions (see
// IsProtectedSubpath / Equal): on an atypical volume (e.g. a case-sensitive
// macOS APFS volume) it treats a differently-cased path as matching, which is
// safe only when the effect is to exclude more, never to widen an allow gate.
func CaseInsensitiveFS() bool {
	return runtime.GOOS == osWindows || runtime.GOOS == osDarwin
}

// Equal reports whether two paths refer to the same location, honoring the host
// OS's case sensitivity (see CaseInsensitiveFS). Both inputs are cleaned and
// slash-normalized before comparison. Like IsProtectedSubpath, this is intended
// for EXCLUSION matching (e.g. protected files), not fail-closed containment.
func Equal(a, b string) bool {
	a = filepath.Clean(filepath.FromSlash(a))
	b = filepath.Clean(filepath.FromSlash(b))
	if CaseInsensitiveFS() {
		return strings.EqualFold(a, b)
	}
	return a == b
}

// IsRelativeTraversal reports whether rel escapes its base directory.
// It accepts both OS-native paths and Git-style slash-normalized paths.
func IsRelativeTraversal(rel string) bool {
	return rel == ".." || strings.HasPrefix(rel, "../") || strings.HasPrefix(rel, `..\`)
}

// ToRelativePath converts an absolute path to relative.
// Returns empty string if the path is outside the working directory.
func ToRelativePath(absPath, cwd string) string {
	absPath = normalizeMSYSPath(absPath)
	cwd = normalizeMSYSPath(cwd)

	// On Windows, MSYS/Git Bash sometimes omits the drive letter, producing
	// paths like /Users/... that filepath.IsAbs doesn't recognize. Prepend
	// the drive letter from cwd so filepath.Rel can match them.
	if runtime.GOOS == osWindows && len(absPath) > 0 && absPath[0] == '/' && len(cwd) >= 2 && cwd[1] == ':' {
		absPath = cwd[:2] + absPath
	}

	if !filepath.IsAbs(absPath) {
		return absPath
	}
	relPath, err := filepath.Rel(cwd, absPath)
	if err != nil || IsRelativeTraversal(relPath) {
		return ""
	}

	return relPath
}

// normalizeMSYSPath converts MSYS/Git Bash-style paths (e.g., /c/Users/...)
// to Windows-style paths (e.g., C:/Users/...) so that filepath.IsAbs and
// filepath.Rel work correctly. On non-Windows platforms this is a no-op.
// Claude Code on Windows outputs MSYS paths in its transcript, but Go's
// filepath package only recognizes Windows-style absolute paths.
func normalizeMSYSPath(p string) string {
	if runtime.GOOS != osWindows {
		return p
	}
	// MSYS paths look like /c/Users/... where the second char is a drive letter
	if len(p) >= 3 && p[0] == '/' && unicode.IsLetter(rune(p[1])) && p[2] == '/' {
		return string(unicode.ToUpper(rune(p[1]))) + ":" + p[2:]
	}
	return p
}

// SessionMetadataDirFromSessionID returns the path to a session's metadata directory
// for the given Entire session ID. The sessionID must be the full, already date-prefixed
// Entire session identifier as stored on disk, not an agent-specific or raw Claude ID.
func SessionMetadataDirFromSessionID(sessionID string) string {
	return EntireMetadataDir + "/" + sessionID
}

// SubagentsDir returns the directory an agent stores a session's subagent
// transcripts in: <transcriptDir>/<sessionID>/subagents.
//
// This layout lives here, in the leaf paths package, because it is needed on both
// sides of the import graph — the lifecycle dispatcher and the strategy, review,
// and agentimport packages all resolve it, and those cannot import each other.
// Before it was named it existed as five copies of the same filepath.Join, which
// is how the SubagentEnd path came to disagree with the turn-end path about where
// subagent transcripts live.
//
// sessionID is the *agent's* session ID (the transcript file's own basename), not
// the date-prefixed Entire session ID.
func SubagentsDir(transcriptDir, sessionID string) string {
	return filepath.Join(transcriptDir, sessionID, "subagents")
}

// AgentTranscriptFileName returns the file name an agent writes a subagent's
// transcript under: agent-<agentID>.jsonl.
func AgentTranscriptFileName(agentID string) string {
	return "agent-" + agentID + ".jsonl"
}

// ExtractSessionIDFromTranscriptPath attempts to extract a session ID from a transcript path.
// Claude transcripts are stored at ~/.claude/projects/<project>/sessions/<id>.jsonl
// If the path doesn't match expected format, returns empty string.
func ExtractSessionIDFromTranscriptPath(transcriptPath string) string {
	// Try to extract from typical path: ~/.claude/projects/<project>/sessions/<id>.jsonl
	parts := strings.Split(filepath.ToSlash(transcriptPath), "/")
	for i, part := range parts {
		if part == "sessions" && i+1 < len(parts) {
			// Return filename without extension
			filename := parts[i+1]
			if strings.HasSuffix(filename, ".jsonl") {
				return strings.TrimSuffix(filename, ".jsonl")
			}
			return filename
		}
	}
	return ""
}

